def resolve(path, cwd, links):
    # Start with cwd if path is relative, otherwise start with root
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')
        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current path is a symlink
            if current in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[current]

                # If target starts with '/', it's absolute
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    # Go back to parent directory
                    if current != '/':
                        current = current.rsplit('/', 1)[0]
                        if current == '':
                            current = '/'
                    remaining = target

                # Continue processing with the target
                break
        else:
            # All components processed without encountering a symlink
            break

    # Remove trailing slash (except for root)
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

